class AddEventDialogController{constructor($scope,$mdDialog,NWData,toastrService,rateJobService,job,dispatherName,contactId){this.$mdDialog=$mdDialog;this.NWData=NWData;this.toastrService=toastrService;this.rateJobService=rateJobService;this._dispatherName=dispatherName;this._contactId=contactId;this._job=job;this.eventTypes=[];this.selectedEvent=null;this.eventForm=$scope.eventForm;let time=new Date;time.setSeconds(0);time.setMilliseconds(0);this.event={jobId:job.id,jobNumber:job.jobNo,clientCode:job.client,eventDate:new Date,eventTime:time,eventType:"",notes:""};this._initialiseData()}_initialiseData(){this.NWData.getEventTypes().then(data=>{this.eventTypes=data;const otherEvent=this.eventTypes.find(eventType=>eventType.text==="Other");if(otherEvent){this.selectedEvent=otherEvent}})}async submit(event){try{if(!this.eventForm.$valid){this.toastrService.showWarningToast("Please complete all the required fields.");return}const eventId=this.selectedEvent.id;const eventName=this.selectedEvent.text;if(eventId==="7"||eventId==="92"){this.NWData.exsalerateActivity(eventName,event.notes,this._clientId,event.jobNumber,this._dispatherName)}if(eventId==="48"||eventId==="52"||eventId==="54"||eventId==="60"||eventId==="6"){const newNote=eventName+":"+event.notes;await this.NWData.addNote(event.jobId,newNote,FirstName,false)}await this.NWData.addEvent(event.jobNumber,this._job.clientId,this._job.contact,this._contactId,this._job.courierData.courierID,this._job.id,this._job.jobType,this._dispatherName,event.notes,eventId);if(eventId==="6"){this.NWData.voidJob(this._job.id)}angular.element(".eventForm").hide()}catch(error){this.toastrService.showErrorToast(error.message)}this.$mdDialog.hide()}cancel(){this.$mdDialog.cancel()}}